// Detect ATS + competitor mentions in the homepage HTML, and find the careers link to fetch next.
// HTML capped at 150KB: ATS embeds and nav links live near the top, and the task runner has a 30s budget per node.
// Long unbroken alphanumeric runs (base64 data URIs, inline blobs) are blanked first and the subdomain patterns are
// word-anchored and length-bounded: unbounded ([a-z0-9-]+) backtracked quadratically on those runs and aborted the runner.
const a = $('Load accounts to scan').item.json;
const r = $json || {};
const html = String(r.body || '').slice(0, 150000).replace(/[A-Za-z0-9+\/=_-]{120,}/g, ' ');
const status = Number(r.statusCode) || null;
const title = (html.match(/<title[^>]*>([^<]{0,200})/i) || [,''])[1].trim();
const ATS = [
  ['greenhouse', /(?:job-boards|boards)\.greenhouse\.io\/([a-z0-9_-]+)/i], ['greenhouse', /grnh\.se\/([a-z0-9_-]+)/i],
  ['lever', /jobs\.lever\.co\/([a-z0-9_-]+)/i], ['ashby', /jobs\.ashbyhq\.com\/([a-z0-9_-]+)/i],
  ['workable', /apply\.workable\.com\/([a-z0-9_-]+)/i], ['workable', /\b([a-z0-9-]{1,63})\.workable\.com/i],
  ['smartrecruiters', /(?:jobs|careers)\.smartrecruiters\.com\/([a-z0-9_-]+)/i],
  ['teamtailor', /\b([a-z0-9-]{1,63})\.teamtailor\.com/i], ['recruitee', /\b([a-z0-9-]{1,63})\.recruitee\.com/i],
  ['personio', /\b([a-z0-9-]{1,63})\.jobs\.personio\.(?:de|com)/i], ['bamboohr', /\b([a-z0-9-]{1,63})\.bamboohr\.com/i],
  ['workday', /\b([a-z0-9-]{1,63})\.(?:wd\d+\.)?myworkdayjobs\.com/i], ['pinpoint', /\b([a-z0-9-]{1,63})\.pinpointhq\.com/i],
  ['jazzhr', /\b([a-z0-9-]{1,63})\.applytojob\.com/i], ['breezy', /\b([a-z0-9-]{1,63})\.breezy\.hr/i],
  ['bullhorn', /bullhornstaffing\.com|bullhorn\.com\/careers|bhjobs/i], ['jobadder', /jobadder\.com/i], ['vincere', /vincere\.io/i],
  ['hibob', /\b([a-z0-9-]{1,63})\.hibob\.com/i], ['rippling', /ats\.rippling\.com\/([a-z0-9_-]+)/i]
];
const COMP = [['remote', /remote\.com/i], ['oyster', /oysterhr\.com/i], ['papaya', /papayaglobal\.com/i], ['omnipresent', /omnipresent\.com/i],
  ['multiplier', /usemultiplier\.com/i], ['gp', /globalization-partners\.com|\bg-p\.com/i], ['velocity', /velocityglobal\.com/i], ['own_brand', /own_brand\.com/i], ['rippling', /rippling\.com/i]];
const find = (list) => { const out = []; for (const [n, re] of list) { const m = html.match(re); if (m) out.push({ n, token: (m[1] || '').toLowerCase() || null, link: m[0] }); } return out; };
const ats = find(ATS); const comp = find(COMP).map(x => x.n);
// careers links: only scan anchor tags, capped, so the regex work stays small
const links = new Set();
const re = /<a[^>]{0,300}href=["']([^"'#]{1,300})["'][^>]{0,300}>([^<]{0,80})/gi; let m; let guard = 0;
while ((m = re.exec(html)) && links.size < 8 && guard++ < 2000) {
  const href = m[1], text = m[2];
  if (/career|jobs?\b|vacanc|join[- ]?us|work[- ]?(with|for)[- ]?us|we-?re-?hiring|opportunit/i.test(href + ' ' + text)) {
    let u = href;
    if (u.startsWith('//')) u = 'https:' + u; else if (u.startsWith('/')) u = 'https://' + a.domain + u; else if (!/^https?:/i.test(u)) u = 'https://' + a.domain + '/' + u;
    if (!/mailto:|tel:|\.(pdf|jpg|png)$/i.test(u)) links.add(u);
  }
}
const careers = [...links];
const careers_url = careers.find(u => ATS.some(([, r2]) => r2.test(u))) || careers[0] || null;
return { json: { ...a, http_status: status, title, ats: ats[0] ? ats[0].n : null, ats_token: ats[0] ? ats[0].token : null,
  ats_links: ats.map(x => x.link), competitor_mentions: comp, careers_links: careers, careers_url,
  need_careers_fetch: !!(careers_url && !ats[0]) } };

// Second pass on the careers page: ATS embeds usually live here, not on the homepage. HTML capped at 150KB.
// Long alphanumeric runs blanked and subdomain patterns word-anchored and bounded, same as Scan homepage, to stay inside the runner's 30s budget.
const s = $('Scan homepage').item.json;
const html = String(($json || {}).body || '').slice(0, 150000).replace(/[A-Za-z0-9+\/=_-]{120,}/g, ' ');
const ATS = [
  ['greenhouse', /(?:job-boards|boards)\.greenhouse\.io\/([a-z0-9_-]+)/i], ['greenhouse', /grnh\.se\/([a-z0-9_-]+)/i], ['greenhouse', /boards-api\.greenhouse\.io\/v1\/boards\/([a-z0-9_-]+)/i],
  ['lever', /jobs\.lever\.co\/([a-z0-9_-]+)/i], ['ashby', /jobs\.ashbyhq\.com\/([a-z0-9_-]+)/i],
  ['workable', /apply\.workable\.com\/([a-z0-9_-]+)/i], ['workable', /\b([a-z0-9-]{1,63})\.workable\.com/i],
  ['smartrecruiters', /(?:jobs|careers)\.smartrecruiters\.com\/([a-z0-9_-]+)/i],
  ['teamtailor', /\b([a-z0-9-]{1,63})\.teamtailor\.com/i], ['teamtailor', /teamtailor/i], ['recruitee', /\b([a-z0-9-]{1,63})\.recruitee\.com/i],
  ['personio', /\b([a-z0-9-]{1,63})\.jobs\.personio\.(?:de|com)/i], ['bamboohr', /\b([a-z0-9-]{1,63})\.bamboohr\.com/i],
  ['workday', /\b([a-z0-9-]{1,63})\.(?:wd\d+\.)?myworkdayjobs\.com/i], ['pinpoint', /\b([a-z0-9-]{1,63})\.pinpointhq\.com/i],
  ['jazzhr', /\b([a-z0-9-]{1,63})\.applytojob\.com/i], ['breezy', /\b([a-z0-9-]{1,63})\.breezy\.hr/i],
  ['bullhorn', /bullhornstaffing\.com|bullhorn\.com\/careers|bhjobs/i], ['jobadder', /jobadder\.com/i], ['vincere', /vincere\.io/i],
  ['hibob', /\b([a-z0-9-]{1,63})\.hibob\.com/i], ['rippling', /ats\.rippling\.com\/([a-z0-9_-]+)/i]
];
const COMP = [['remote', /remote\.com/i], ['oyster', /oysterhr\.com/i], ['papaya', /papayaglobal\.com/i], ['omnipresent', /omnipresent\.com/i],
  ['multiplier', /usemultiplier\.com/i], ['gp', /globalization-partners\.com|\bg-p\.com/i], ['velocity', /velocityglobal\.com/i], ['own_brand', /own_brand\.com/i], ['rippling', /rippling\.com/i]];
let ats = null, token = null; const atsLinks = [...(s.ats_links || [])];
for (const [n, re] of ATS) { const m = html.match(re); if (m) { if (!ats) { ats = n; token = (m[1] || '').toLowerCase() || null; } atsLinks.push(m[0]); } }
if (!ats) for (const [n, re] of ATS) { const m = String(s.careers_url || '').match(re); if (m) { ats = n; token = (m[1] || '').toLowerCase() || null; break; } }
const comp = new Set(s.competitor_mentions || []); for (const [n, re] of COMP) if (re.test(html)) comp.add(n);
return { json: { ...s, ats: s.ats || ats, ats_token: s.ats_token || token, ats_links: [...new Set(atsLinks)], competitor_mentions: [...comp], pages_fetched: ['home', 'careers'] } };

// Fan-in: items arrive from Scan careers page (fetched) or straight from the IF (no careers fetch). One payload shape for the RPC.
let s = null; try { s = $('Scan careers page').item.json; } catch (e) {}
if (!s || !s.account_id) s = $json;
return { json: {
  p_account_id: s.account_id, p_http_status: s.http_status || null, p_title: (s.title || '').slice(0, 200) || null,
  p_ats_provider: s.ats || null, p_ats_token: s.ats_token || null, p_careers_url: s.careers_url || null,
  p_ats_links: s.ats_links || [], p_careers_links: s.careers_links || [], p_competitor_mentions: s.competitor_mentions || [],
  p_pages_fetched: s.pages_fetched || ['home']
} };
